INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H01', 'Hotel Malioboro Inn', 'Jl. Malioboro No. 52, Gedongtengen, Kota Yogyakarta', 'Kota Yogyakarta', 4, 'Lima menit jalan kaki ke Jalan Malioboro, Pasar Beringharjo, dan Titik Nol. Pilihan tepat untuk wisata kuliner dan belanja di pusat kota.', 'https://images.unsplash.com/photo-1549294413-26f195200c16?w=1200&q=80&fit=crop&crop=center', 'Malioboro');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H02', 'Grand Palace Yogyakarta', 'Jl. Rotowijayan No. 1, Kraton, Kota Yogyakarta', 'Kota Yogyakarta', 5, 'Hotel mewah bersejarah di jantung Kraton Yogyakarta. Arsitektur Jawa klasik berpadu fasilitas bintang lima, langkah kaki dari alun-alun.', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1200&q=80&fit=crop&crop=center', 'Kraton');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H03', 'Ibis Styles Yogyakarta', 'Jl. Sosrokusuman No. 9, Gedongtengen, Kota Yogyakarta', 'Kota Yogyakarta', 3, 'Hotel budget ceria dekat Malioboro dengan desain modern. Cocok untuk backpacker dan pelancong muda yang ingin hemat tanpa mengorbankan kenyamanan.', 'https://images.unsplash.com/photo-1607320879139-1bb689f6a68f?w=1200&q=80&fit=crop&crop=center', 'Sosrokusuman');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H04', 'Neo Malioboro Hotel', 'Jl. Pasar Kembang No. 37, Gedongtengen, Kota Yogyakarta', 'Kota Yogyakarta', 3, 'Tepat di pintu masuk Malioboro, hotel ini menawarkan kamar nyaman dengan harga terjangkau. Restoran rooftop dengan pemandangan kota memukau.', 'https://images.unsplash.com/photo-1701568129402-0d4541e3dab7?w=1200&q=80&fit=crop&crop=center', 'Malioboro');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H05', 'Tentrem Hotel & Convention', 'Jl. AM Sangaji No. 72A, Jetis, Kota Yogyakarta', 'Kota Yogyakarta', 5, 'Hotel bintang 5 kontemporer dengan convention center terbesar di Yogyakarta. Interior memadukan modernitas dengan sentuhan batik dan wayang.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=1200&q=80&fit=crop&crop=center', 'Sudirman');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H06', 'Hotel Pesona Jogja', 'Jl. Prawirotaman No. 17, Mergangsan, Kota Yogyakarta', 'Kota Yogyakarta', 3, 'Berlokasi di kawasan seni Prawirotaman yang trendi. Galeri seni di lobi, kafe berkonsep vintage, dan dekat restoran-restoran internasional.', 'https://images.unsplash.com/photo-1607320895054-c5c543e9a069?w=1200&q=80&fit=crop&crop=center', 'Prawirotaman');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H07', 'Melia Purosani Hotel', 'Jl. Suryodiningratan No. 31, Mantrijeron, Kota Yogyakarta', 'Kota Yogyakarta', 5, 'Hotel internasional chain Meliá dengan kolam renang rooftop, spa mewah, dan restoran all-day dining. Akses mudah ke pusat perbelanjaan.', 'https://images.unsplash.com/photo-1550504969-937eb02c18b3?w=1200&q=80&fit=crop&crop=center', 'Pusat Kota');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H08', 'Royal Ambarrukmo', 'Jl. Laksda Adisucipto No. 81, Depok, Sleman', 'Sleman', 5, 'Ikon kemewahan Yogyakarta sejak 1966 dengan latar belakang sejarah kerajaan. Koleksi antik dan taman tropis yang asri di tengah kota.', 'https://images.unsplash.com/photo-1536269404660-0a8d4e88bf1b?w=1200&q=80&fit=crop&crop=center', 'Depok');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H09', 'Whiz Prime Hotel Malioboro', 'Jl. Dagen No. 85, Gedongtengen, Kota Yogyakarta', 'Kota Yogyakarta', 3, 'Hotel mid-range strategis di belakang Jalan Malioboro. Sarapan prasmanan dengan menu tradisional Jawa menjadi nilai lebih tersendiri.', 'https://images.unsplash.com/photo-1607320895054-c5c543e9a069?w=1200&q=80&fit=crop&crop=center', 'Malioboro');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H10', 'Boutique Hotel Tjokro', 'Jl. Tentara Pelajar No. 37, Jetis, Kota Yogyakarta', 'Kota Yogyakarta', 4, 'Boutique hotel bergaya kolonial Belanda di kawasan Kotabaru yang tenang. Arsitektur heritage tahun 1930-an dengan kolam renang outdoor yang menawan.', 'https://images.unsplash.com/photo-1596178060810-72f53ce9a65c?w=1200&q=80&fit=crop&crop=center', 'Kotabaru');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H11', 'Prambanan Heritage Resort', 'Jl. Raya Solo-Yogya Km 16, Bokoharjo, Prambanan, Sleman', 'Sleman', 5, 'Resort tenang dengan kolam renang dan taman tropis, hanya 2 km dari Candi Prambanan. Cocok untuk menikmati sunset dan pertunjukan Sendratari Ramayana.', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=1200&q=80&fit=crop&crop=center', 'Prambanan');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H12', 'Plataran Borobudur & Jogja', 'Jl. Magelang Km 10, Medari, Sleman', 'Sleman', 5, 'Resor butik eksklusif dengan nuansa alam Jawa yang kental. Villa-villa pribadi dengan taman tropis dan akses mudah ke Candi Borobudur.', 'https://images.unsplash.com/photo-1627448449276-8c139d0790a6?w=1200&q=80&fit=crop&crop=center', 'Medari');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H13', 'Gaia Oasis Resort Jogja', 'Jl. Kaliurang Km 18.5, Hargobinangun, Pakem, Sleman', 'Sleman', 4, 'Resort di lereng Merapi dengan udara sejuk Kaliurang. Aktivitas outbound, trekking hutan pinus, dan pemandangan Gunung Merapi yang spektakuler.', 'https://images.unsplash.com/photo-1445019980597-93fa8acb246c?w=1200&q=80&fit=crop&crop=center', 'Kaliurang');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H14', 'Eastparc Hotel Yogyakarta', 'Jl. Laksda Adisucipto Km 6.5, Tajem, Maguwoharjo, Depok, Sleman', 'Sleman', 4, 'Hotel modern di kawasan timur Yogyakarta dekat jalan tol. Kolam renang olympic-size dan pusat kebugaran menjadi keunggulan hotel ini.', 'https://images.unsplash.com/photo-1596178060810-72f53ce9a65c?w=1200&q=80&fit=crop&crop=center', 'Tajem');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H15', 'Hyatt Regency Yogyakarta', 'Jl. Palagan Tentara Pelajar, Gonjagan, Ngaglik, Sleman', 'Sleman', 5, 'Hotel internasional di atas bukit dengan pemandangan 360° Kota Yogyakarta dan Gunung Merapi. Dua kolam renang, lapangan golf, dan spa premium.', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?w=1200&q=80&fit=crop&crop=center', 'Gonjagan');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H16', 'Sheraton Mustika Resort & Spa', 'Jl. Laksda Adisucipto, Maguwoharjo, Depok, Sleman', 'Sleman', 5, 'Resort gaya Jawa mewah dengan kolam renang besar, spa Mustika Ratu, dan fasilitas MICE lengkap. Dekat Bandara Adisutjipto lama.', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=1200&q=80&fit=crop&crop=center', 'Maguwoharjo');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H17', 'Hotel Kaliurang Indah', 'Jl. Astomulyo 99, Hargobinangun, Pakem, Sleman', 'Sleman', 3, 'Hotel keluarga di kawasan wisata Kaliurang dengan udara pegunungan yang segar. Kolam renang air panas alami dan jalur trekking ke Hutan Pinus Mangunan.', 'https://images.unsplash.com/photo-1549847148-afd367dd3e53?w=1200&q=80&fit=crop&crop=center', 'Kaliurang');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H18', 'Sleman Yogyakarta Hotel', 'Jl. Affandi No. 5, Caturtunggal, Depok, Sleman', 'Sleman', 3, 'Hotel terjangkau dekat Universitas Gadjah Mada dan pusat kuliner Yogyakarta. Cocok untuk wisata akademik dan keluarga yang mengunjungi mahasiswa.', 'https://images.unsplash.com/photo-1607320879139-1bb689f6a68f?w=1200&q=80&fit=crop&crop=center', 'Depok');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H19', 'Griya Palagan Bantul (Demo)', 'Kawasan Kasihan, Kabupaten Bantul (alamat simulasi)', 'Bantul', 4, 'Akomodasi simulasi di Kasihan, Bantul, dengan fasilitas ruang pertemuan dan kolam renang; ketersediaan dan harga adalah data demo.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=1200&q=80&fit=crop&crop=center', 'Kasihan');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H20', 'Parangtritis Beach Hotel', 'Jl. Parangtritis Km 27, Kretek, Bantul', 'Bantul', 3, 'Satu-satunya hotel berbintang tepat di tepi Pantai Parangtritis dengan pemandangan laut selatan yang dramatis. Saksikan matahari terbenam dari kamar.', 'https://images.unsplash.com/photo-1584132869994-873f9363a562?w=1200&q=80&fit=crop&crop=center', 'Parangtritis');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H21', 'Dpavilion Bantul Resort', 'Jl. Imogiri Timur Km 12, Siluk, Imogiri, Bantul', 'Bantul', 4, 'Resort tenang di perbukitan Imogiri dengan konsep eco-tourism. Kolam renang infinity dengan latar sawah hijau dan pemandangan Bukit Menoreh yang memukau.', 'https://images.unsplash.com/photo-1610641818989-c2051b5e2cfd?w=1200&q=80&fit=crop&crop=center', 'Imogiri');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H22', 'Griya Sonosewu (Demo)', 'Kawasan Kasihan, Kabupaten Bantul (alamat simulasi)', 'Bantul', 3, 'Hotel mid-range di perbatasan Kota Yogyakarta dan Bantul. Akses mudah ke Bandara YIA, pusat perbelanjaan, dan wisata alam Bantul.', 'https://images.unsplash.com/photo-1607320895054-c5c543e9a069?w=1200&q=80&fit=crop&crop=center', 'Kasihan');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H23', 'Sambi Homestay Bantul (Demo)', 'Kawasan Pajangan, Kabupaten Bantul (alamat simulasi)', 'Bantul', 4, 'Villa dan resort tersembunyi di tengah kebun durian dan rambutan. Spa organik menggunakan bahan herbal lokal, cocok untuk detox dan wellness retreat.', 'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=1200&q=80&fit=crop&crop=center', 'Pajangan');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H24', 'Grand Keisha Hotel', 'Jl. Ring Road Selatan No. 111, Tamanan, Banguntapan, Bantul', 'Bantul', 4, 'Hotel modern di ring road selatan Yogyakarta. Fasilitas lengkap dengan kolam renang, pusat kebugaran, dan restoran dengan menu masakan Indonesia dan internasional.', 'https://images.unsplash.com/photo-1596178060810-72f53ce9a65c?w=1200&q=80&fit=crop&crop=center', 'Sanden');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H25', 'Puri Saron Bantul', 'Jl. Parangtritis Km 6.5, Sewon, Bantul', 'Bantul', 3, 'Hotel bernuansa villa Bali di kawasan Sewon Bantul. Kolam renang private, restoran terbuka, dan dekat sentra kerajinan gerabah Kasongan.', 'https://images.unsplash.com/photo-1563911302283-d2bc129e7570?w=1200&q=80&fit=crop&crop=center', 'Sewon');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H26', 'Bukit Indah Resort Wonosari', 'Jl. Wonosari-Baran Km 3, Baran, Wonosari, Gunungkidul', 'Gunungkidul', 4, 'Resort di atas bukit dengan panorama Kota Wonosari dan kawasan karst Gunungkidul. Kolam renang infinity yang menghadap perbukitan hijau yang menakjubkan.', 'https://images.unsplash.com/photo-1445019980597-93fa8acb246c?w=1200&q=80&fit=crop&crop=center', 'Wonosari');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H27', 'Indra Beach Inn Krakal', 'Pantai Krakal, Ngestirejo, Tanjungsari, Gunungkidul', 'Gunungkidul', 3, 'Penginapan tepi pantai yang nyaman dengan akses langsung ke Pantai Krakal. Snorkeling, kayak, dan menikmati seafood segar langsung dari nelayan setempat.', 'https://images.unsplash.com/photo-1571003123771-bd6a099dd83a?w=1200&q=80&fit=crop&crop=center', 'Krakal');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H28', 'Sunset View Hotel Wediombo', 'Jl. Wediombo, Jepitu, Girisubo, Gunungkidul', 'Gunungkidul', 3, 'Hotel paling dekat dengan Pantai Wediombo, surganya para surfer. Sunset dari sini adalah salah satu yang terbaik di Yogyakarta, difoto jutaan wisatawan.', 'https://images.unsplash.com/photo-1584132869994-873f9363a562?w=1200&q=80&fit=crop&crop=center', 'Wediombo');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H29', 'Cave Tubing Resort Kalisuci', 'Dusun Jetis, Semanu, Gunungkidul', 'Gunungkidul', 3, 'Resort unik di kawasan gua karst Semanu. Paket wisata cave tubing di Sungai Kalisuci yang mengalir di bawah tanah tersedia setiap hari.', 'https://images.unsplash.com/photo-1549847148-afd367dd3e53?w=1200&q=80&fit=crop&crop=center', 'Semanu');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H30', 'Baron Beach Eco Resort', 'Pantai Baron, Kemadang, Tanjungsari, Gunungkidul', 'Gunungkidul', 4, 'Eco-resort premium di kawasan Pantai Baron dengan konsep sustainable tourism. Restoran seafood dari hasil tangkapan nelayan lokal, kolam renang, dan taman mangrove.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?w=1200&q=80&fit=crop&crop=center', 'Tanjungsari');
INSERT INTO hotels (id, name, address, city, rating, description, image_url, area) VALUES ('H31', 'YIA Airport Hotel', 'Jl. Wates Km 42, Temon, Kulon Progo', 'Kulon Progo', 3, 'Hotel praktis 10 menit dari Bandara Internasional Yogyakarta, dengan shuttle bandara gratis. Ideal untuk transit atau penerbangan pagi.', 'https://images.unsplash.com/photo-1551016043-06ec2173531b?w=1200&q=80&fit=crop&crop=center', 'Bandara YIA');
